import {
    Table,
    ReferenceColumn,
    TranslatedFieldColumn,
    BooleanColumn,
    JsonColumn,
    DomainIdColumn,
    GenericColumn,
    GuidColumn,
} from '../../db'

export const par_component = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    audit: true,
    display: 'name',
    extends: 'sys_metadata',
    extensible: true,
    label: 'Par Component',
    name: 'par_component',
    schema: {
        requested_by: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'clear',
            label: 'Requested by',
            referenceTable: 'sys_user',
        }),
        name: TranslatedFieldColumn({
            label: [
                {
                    hint: 'Name data visualization item',
                    label: 'Name',
                    plural: 'Names',
                },
            ],
            maxLength: 100,
        }),
        description: TranslatedFieldColumn({
            label: 'Description',
            maxLength: 1000,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        properties: JsonColumn({
            label: [
                {
                    hint: 'JSON, configuration of the component',
                    label: 'Properties',
                    plural: 'Properties',
                },
            ],
            maxLength: 8000,
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which this component belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
        }),
        certified: BooleanColumn({
            default: false,
            label: 'Certified',
        }),
        required_translations: GenericColumn({
            attributes: {
                json_view: true,
            },
            columnType: 'json_translations',
            label: [
                {
                    hint: 'JSON Array, holding the translations required by this screen',
                    label: 'Required translations',
                    plural: 'Required translations',
                },
            ],
            maxLength: 8000,
        }),
        macroponent: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: 'Macroponent',
            referenceTable: 'sys_ux_macroponent',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                },
            ],
            primary: true,
        }),
    },
    textIndex: true,
})
